'use strict';
const seed=[
{id:'rr-001',title:'Star Explorer #1',category:'Comics',year:'2024',condition:'Near mint',location:'Comic box A',color:'#234d63',art:'bands',notes:'Fictional first printing. Bright cover; slight wear at the lower spine.',acquired:'2026-09-12',source:'Collector fair',events:[{date:'2026-09-12',text:'Acquired at a collector fair. Owner-entered account.'}]},
{id:'rr-002',title:'Midnight Session',category:'Records',year:'1961',condition:'Very good',location:'Record shelf 2',color:'#803e3f',art:'disc',notes:'Fictional stereo pressing. Sleeve has light edge wear.',acquired:'2026-08-20',source:'Local record shop',events:[{date:'2026-08-20',text:'Acquired at a local record shop. Receipt not attached.'}]},
{id:'rr-003',title:'Forest Guardian',category:'Cards',year:'2023',condition:'Excellent',location:'Card binder',color:'#46634b',art:'bands',notes:'Fictional illustrated card, ungraded.',acquired:'2026-10-03',source:'Trade',events:[{date:'2026-10-03',text:'Acquired through a trade. Owner-entered account.'}]},
{id:'rr-004',title:'The Quiet Shore',category:'Art',year:'2022',condition:'Excellent',location:'Flat file',color:'#c7d6ce',ink:'#29483e',art:'bands',notes:'Fictional editioned print, 12 of 50.',acquired:'2026-07-04',source:'Artist studio',events:[{date:'2026-07-04',text:'Acquired from an artist studio. Owner-entered account.'}]},
{id:'rr-005',title:'Collected Worlds',category:'Books',year:'1984',condition:'Good',location:'Bookcase',color:'#bb9c60',ink:'#302b28',art:'bands',notes:'Fictional illustrated hardcover.',acquired:'2026-10-10',source:'Book fair',events:[{date:'2026-10-10',text:'Acquired at a book fair. Owner-entered account.'}]},
{id:'rr-006',title:'Ocean Signals',category:'Records',year:'1978',condition:'Very good',location:'Record shelf 2',color:'#26585d',art:'disc',notes:'Fictional instrumental album.',acquired:'2026-10-17',source:'Local record shop',events:[{date:'2026-10-17',text:'Acquired at a local record shop. Owner-entered account.'}]},
{id:'rr-007',title:'Star Explorer #1 · reading copy',category:'Comics',year:'2023',condition:'Good',location:'Comic box A',color:'#aa4b31',art:'bands',notes:'Fictional issue with visible reading wear.',acquired:'2026-10-20',source:'Collector fair',events:[{date:'2026-10-20',text:'Acquired at a collector fair. Owner-entered account.'}]},
{id:'rr-008',title:'Orbit Mk II',category:'Toys',year:'2020',condition:'Good',location:'Display cabinet',color:'#ded7c8',ink:'#302b28',art:'bands',notes:'Fictional wind-up toy. No original packaging.',acquired:'2026-10-22',source:'Gift',events:[{date:'2026-10-22',text:'Received as a gift. Owner-entered account.'}]}
];
const key='relicrat-design-review-v2';let storageError='';let items;
try{const saved=localStorage.getItem(key);items=saved?JSON.parse(saved):structuredClone(seed);if(!Array.isArray(items)||items.some(x=>!x||typeof x.id!=='string'||typeof x.title!=='string'||!Array.isArray(x.events)))throw Error('Invalid saved collection');}catch(e){items=structuredClone(seed);storageError='Saved demo data could not be loaded. Changes will not overwrite it. Export your browser data before resetting this demo.';}
let query='',category='All',condition='All',sort='recent',view='grid';
const main=document.querySelector('main');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Comics','Records','Cards','Art','Books','Toys','Other'];
const options=(values,current)=>values.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('');
function cover(x){
 const cells={Comics:'0 0 458 534',Cards:'458 0 458 534',Records:'916 0 458 534',Art:'0 534 458 611',Books:'458 534 458 611',Toys:'916 534 458 611'};
 if(x.art&&cells[x.category]){const [cx,cy,cw,ch]=cells[x.category].split(' ');return `<div class="cover collectible-image"><svg viewBox="${cells[x.category]}" role="img" aria-label="${esc(x.category)}: fictional collectible illustration, not a photo of this physical copy"><svg x="${cx}" y="${cy}" width="${cw}" height="${ch}" viewBox="${cells[x.category]}" overflow="hidden"><image href="../assets/fictional-collectibles-EXPLORATORY.png" width="1374" height="1145"/></svg></svg></div>`;}
 return `<div class="cover" style="--cover:#e8eee9;--coverInk:#29483e"><span>${esc(x.category)} · ${esc(x.year||'Year unknown')}</span><strong>${esc(x.title)}</strong><span class="no-photo">No photo added</span><small>Physical copy</small></div>`;
}
function card(x){return `<button class="item" data-id="${esc(x.id)}">${cover(x)}<div><h3>${esc(x.title)}</h3><small>${esc(x.year||'Year unknown')} · ${esc(x.category)}</small></div><small>${esc(x.condition)}</small></button>`;}
function filtered(){return items.filter(x=>(category==='All'||x.category===category)&&(condition==='All'||x.condition===condition)&&[x.title,x.notes,x.location,x.category].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='title'?a.title.localeCompare(b.title):b.acquired.localeCompare(a.acquired));}
function collection(){main.innerHTML=`<div class="titlebar"><div><h1>My collection</h1><p class="muted">${items.length} physical copies. Every one has a story.</p></div><div><button id="grid" aria-pressed="${view==='grid'}">Grid</button> <button id="list" aria-pressed="${view==='list'}">List</button></div></div><div class="tools"><label>Search your collection<input id="search" type="search" placeholder="Title, notes, or storage location" value="${esc(query)}"></label><label>Category<select id="category">${options(['All',...categories],category)}</select></label><label>Condition<select id="condition">${options(['All','Near mint','Excellent','Very good','Good','Fair','Unknown'],condition)}</select></label><label>Sort by<select id="sort"><option value="recent" ${sort==='recent'?'selected':''}>Acquisition date</option><option value="title" ${sort==='title'?'selected':''}>Title A–Z</option></select></label></div><p id="count" class="muted" role="status"></p><div id="results"></div>`;results();document.querySelector('#search').oninput=e=>{query=e.target.value;results()};['category','condition','sort'].forEach(id=>document.getElementById(id).onchange=e=>{if(id==='category')category=e.target.value;if(id==='condition')condition=e.target.value;if(id==='sort')sort=e.target.value;results()});['grid','list'].forEach(id=>document.getElementById(id).onclick=()=>{view=id;collection()});}
function results(){const rows=filtered();document.querySelector('#count').textContent=`${rows.length} ${rows.length===1?'copy':'copies'} shown`;document.querySelector('#results').className=view;document.querySelector('#results').innerHTML=rows.length?rows.map(card).join(''):`<div class="empty"><h2>${items.length?'No matching collectibles':'Your collection starts here'}</h2><p>${items.length?'Try another title, or clear the filters.':'Add your first physical copy and preserve what you know about it.'}</p><button id="empty-action">${items.length?'Clear filters':'Add a collectible'}</button></div>`;const empty=document.querySelector('#empty-action');if(empty)empty.onclick=()=>{if(items.length){query='';category=condition='All';collection()}else location.hash='add'};bindCards();}
function bindCards(){document.querySelectorAll('[data-id]').forEach(el=>el.onclick=()=>{location.hash='item/'+encodeURIComponent(el.dataset.id)});}
function home(){const recent=[...items].sort((a,b)=>b.acquired.localeCompare(a.acquired)).slice(0,4);main.innerHTML=`<h1>A place for what you collect.</h1><p class="muted">Keep the objects, the details, and the stories together.</p><div class="summary"><article><h2>Your collection</h2><strong>${items.length}</strong><p>Physical copies across ${new Set(items.map(x=>x.category)).size} categories.</p><a href="#collection">Browse your collection</a></article><article><h2>Keep the story going</h2><p>Record the condition, where you keep it, and how it came into your collection. Unknown details can wait.</p><a href="#add">Catalog your next find</a></article></div><h2>Recent acquisitions</h2><div class="grid">${recent.map(card).join('')}</div>`;bindCards();}
function detail(id){const x=items.find(x=>x.id===id);if(!x){main.innerHTML='<h1>Copy not found</h1><p>This demo record is unavailable.</p><a href="#collection">Back to collection</a>';return}main.innerHTML=`<p><a href="#collection">Back to collection</a></p><div class="detail"><div>${cover(x)}<p class="muted">${x.art?'Generated fictional collectible illustration for visual review; not evidence of this copy’s appearance or condition.':'Add a photo in the production app.'}</p></div><article><div class="titlebar"><div><h1>${esc(x.title)}</h1><p>${esc(x.category)} · ${esc(x.year||'Year unknown')}</p></div><a href="#edit/${encodeURIComponent(x.id)}">Edit copy</a></div><dl><div><dt>Physical copy ID</dt><dd>${esc(x.id)}</dd></div><div><dt>Condition · owner assessment</dt><dd>${esc(x.condition)}</dd></div><div><dt>Storage location</dt><dd>${esc(x.location||'Not assigned')}</dd></div><div><dt>Acquired</dt><dd>${esc(x.acquired||'Unknown')}</dd></div></dl><h2>Collector’s notes</h2><p>${esc(x.notes||'No notes recorded.').replace(/\n/g,'<br>')}</p><h2>Identity</h2><p class="muted">Provisional identification. No catalog item or release is linked in this design review.</p><h2>Provenance & history</h2><p class="muted">Owner-entered history; independent authentication has not been performed.</p><ol class="timeline">${x.events.map(e=>`<li><time>${esc(e.date)}</time>${esc(e.text)}</li>`).join('')}</ol></article></div>`;}
function form(id){const x=id?items.find(x=>x.id===id):null;if(id&&!x){detail(id);return}main.innerHTML=`<p><a href="#${x?'item/'+encodeURIComponent(id):'collection'}">Cancel and go back</a></p><h1>${x?'Edit physical copy':'Add a collectible'}</h1><p class="muted">Start with what you know. You can add details later.</p><form class="form"><label>Title <span class="muted">(required)</span><input name="title" required maxlength="160" value="${esc(x?.title)}" autocomplete="off"></label><div class="form-grid"><label>Category<select name="category">${options(categories,x?.category||'Other')}</select></label><label>Year<input name="year" maxlength="20" value="${esc(x?.year)}" placeholder="Unknown"></label><label>Condition<select name="condition">${options(['Unknown','Near mint','Excellent','Very good','Good','Fair'],x?.condition||'Unknown')}</select></label><label>Storage location<input name="location" maxlength="160" value="${esc(x?.location)}" placeholder="Not assigned"></label><label>Acquisition date<input name="acquired" type="date" value="${esc(x?.acquired)}"></label><label>Acquired from<input name="source" maxlength="160" value="${esc(x?.source)}" placeholder="Shop, trade, gift…"></label></div><label>Notes<textarea name="notes" maxlength="5000">${esc(x?.notes)}</textarea></label><p class="muted">This review saves to this browser only. Photos, catalog linking, and revision-checked saves are provided by the existing application.</p><p class="error" role="alert" id="form-error"></p><div class="actions"><button class="primary" type="submit">${x?'Save changes':'Save physical copy'}</button><button type="button" id="cancel">Cancel</button></div></form>`;document.querySelector('#cancel').onclick=()=>{location.hash=x?'item/'+encodeURIComponent(id):'collection'};document.querySelector('form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.title=data.title.trim();if(!data.title){document.querySelector('#form-error').textContent='Enter a title before saving.';return}if(storageError){document.querySelector('#form-error').textContent=storageError;return}const now=new Date().toISOString().slice(0,10);const next={...x,...data,id:x?.id||crypto.randomUUID(),events:[...(x?.events||[]),{date:now,text:x?'Copy details updated in this design review.':'Physical copy added. '+(data.source?'Acquired from '+data.source+'. ':'')+'Owner-entered account.'}]};const updated=x?items.map(i=>i.id===id?next:i):[...items,next];try{localStorage.setItem(key,JSON.stringify(updated));items=updated;location.hash='item/'+encodeURIComponent(next.id);notify('Physical copy saved on this device.')}catch{document.querySelector('#form-error').textContent='This browser could not save your copy. Keep this form open and try freeing browser storage.'}};}
function brand(){main.innerHTML=`<h1>One identity. A collection of stories.</h1><p>Production proposals extending the approved RelicRat direction. These assets have not been approved as canonical.</p><h2>The wordmark</h2><div class="logo-demo"><img src="../assets/wordmark-PROPOSED.svg" alt="Proposed RELICRAT wordmark"></div><p>Refined curved slab letters, expressive R forms, and a subtle rising rhythm. One color, no compass, no texture. Uppercase is proposed for the mark; use RelicRat in running text.</p><h2>The small mark</h2><div class="icon-demo">${[16,32,64].map(n=>`<figure><img width="${n}" height="${n}" src="../assets/rat-head${n===16?'-small':''}-PROPOSED.svg" alt="Proposed rat silhouette at ${n} pixels"><figcaption>${n} px</figcaption></figure>`).join('')}<img width="80" src="../assets/app-icon-PROPOSED.svg" alt="Proposed app icon"></div><p>Two rounded ears, swept fur, a rounded nose and muzzle, and a distinct neck. The 16 px version removes interior detail. The silhouette is a proposal to review against the original anatomy, not an approved mascot replacement.</p><h2>Color & type</h2><div class="swatches">${[['Ivory','#F7F3E9'],['Charcoal','#302B28'],['Forest','#29483E'],['Burgundy','#823B3D'],['Gold','#B78B43']].map(([n,c])=>`<div class="swatch" style="--swatch:${c}">${n}<br>${c}</div>`).join('')}</div><p>The palette carries forward the canonical document’s prototype values. System sans-serif serves the operating interface. The logo uses original vector lettering and needs no font file.</p><h2>Use in the existing app</h2><p>Import a theme through Appearance, preview it, then apply it. Theme files change supported appearance settings; they do not install this proposed screen layout.</p><div class="actions"><a href="../relicrat-light-PROPOSED.json" download>Download light theme</a><a href="../relicrat-dark-PROPOSED.json" download>Download dark theme</a><a href="../assets/wordmark-PROPOSED.svg" download>Download wordmark SVG</a></div><h2>Mascot extensions</h2><p>All three original references are now preserved in this kit. The primary character image governs anatomy and outfit; the icon sheet supports simplification; the modern-collectibles board governs activities. New character artwork remains proposed pending review.</p><div class="mascot-examples"><figure><img src="../assets/mascot-front-v2-PROPOSED.png" alt="Proposed front-facing RelicRat mascot anatomy study"><figcaption>Front study · proposed</figcaption><a href="../assets/mascot-front-v2-PROPOSED.png" download="mascot-front-v2-PROPOSED.png">Download transparent PNG</a></figure><figure><img src="../assets/mascot-vinyl-v2-PROPOSED.png" alt="Proposed RelicRat mascot carefully holding a record by its outer rim"><figcaption>Vinyl pose · proposed</figcaption><a href="../assets/mascot-vinyl-v2-PROPOSED.png" download="mascot-vinyl-v2-PROPOSED.png">Download transparent PNG</a></figure></div><p>These standalone transparent studies extend the original reference; they do not replace it. The earlier multi-pose sheet is retained as superseded exploration. A complete production turnaround and separated expression library remain future work.</p>`;}
let noticeTimer;function notify(s){clearTimeout(noticeTimer);document.querySelector('#notice').textContent=s;noticeTimer=setTimeout(()=>document.querySelector('#notice').textContent='',5000)}
function route(){const [name,arg]=location.hash.slice(1).split('/');document.querySelectorAll('nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.hash==='#'+(name||'collection'))a.setAttribute('aria-current','page')});if(name==='home')home();else if(name==='item')detail(decodeURIComponent(arg||''));else if(name==='add')form();else if(name==='edit')form(decodeURIComponent(arg||''));else if(name==='brand')brand();else collection();if(storageError)notify(storageError);window.scrollTo(0,0);main.focus({preventScroll:true});}
document.querySelector('#add').onclick=()=>location.hash='add';window.addEventListener('hashchange',route);route();
